mapper.select:
WITH due AS ( SELECT id FROM tb_blockchain_transactions WHERE network IN
#{network}
AND status = 'PENDING' AND (next_retry_at IS NULL OR next_retry_at <= #{now}) ORDER BY requested_at, id LIMIT #{limit} FOR UPDATE SKIP LOCKED ) UPDATE tb_blockchain_transactions target SET status = 'PROCESSING', error_code = NULL, error_message = NULL, next_retry_at = NULL, response_metadata = NULL, updated_at = #{now} FROM due WHERE target.id = due.id RETURNING

WITH stale AS (
    SELECT id FROM tb_blockchain_transactions
     WHERE network IN

         #{network}

       AND status = 'PROCESSING'
       AND updated_at <= #{staleBefore}
     ORDER BY updated_at, id LIMIT #{limit}
     FOR UPDATE SKIP LOCKED
)
UPDATE tb_blockchain_transactions target
   SET status = 'PROCESSING', updated_at = #{now}
  FROM stale WHERE target.id = stale.id
RETURNING
